  selection?: SelectionMask | null,
  worldTransform: LayerTransform = layer.transform,
): TiledPixelStore {
  validateLayer(layer);
  validateTransform(worldTransform);
  validateSelection(selection);
  if (!Number.isInteger(amount) || amount < -255 || amount > 255) {
    throw new RangeError('Brightness amount must be an integer between -255 and 255');
  }
  if (amount === 0) return layer.pixelStore;

  if (selection != null) {
    const patch = adjustBrightness(layer, amount, selection, worldTransform);
    if (patch.width === 0) return layer.pixelStore;
    return layer.pixelStore.write({ ...patch, pixels: new Uint8ClampedArray(patch.pixels) }).store;
  }

  let result = layer.pixelStore;
  const tileSize = layer.pixelStore.tileSize;
  for (let y = 0; y < layer.height; y += tileSize) {
    const height = Math.min(tileSize, layer.height - y);
    for (let x = 0; x < layer.width; x += tileSize) {
      const width = Math.min(tileSize, layer.width - x);
      const source = layer.pixelStore.read({ x, y, width, height });
      const pixels = new Uint8ClampedArray(source);
      let changed = false;
      for (let offset = 0; offset < pixels.length; offset += 4) {
        for (let channel = 0; channel < 3; channel += 1) {
          const original = source[offset + channel] ?? 0;
          const adjusted = Math.max(0, Math.min(255, original + amount));
          if (adjusted !== original) changed = true;
          pixels[offset + channel] = adjusted;
        }
      }
      if (changed) result = result.write({ x, y, width, height, pixels }).store;
    }
  }
  return result;
}

export interface CloneStampOptions {
  /** Brush diameter in document pixels. */
  readonly size: number;
  /** Normalized hard-core radius. */
  readonly hardness: number;
  readonly opacity: number;
  readonly aligned: boolean;
  /** Document-space source position established by Alt/Option-click. */
  readonly sourceX: number;
  readonly sourceY: number;
}

/**
 * Applies a clone stamp stroke, sampling pixels from a source layer and writing them
 * to a destination layer. Returns the smallest layer-local patch containing changed pixels.
 * A no-op returns a 0 x 0 patch.
 * 
 * In aligned mode, the offset between the source position and each destination point
 * is preserved throughout the stroke. In unaligned mode, each dab samples from the
 * same source position.
 */
export function paintCloneStamp(
  destinationLayer: PixelLayer,
  sourceLayer: PixelLayer,
  points: readonly BrushPoint[],
  options: CloneStampOptions,
  selection?: SelectionMask | null,
  destinationWorldTransform: LayerTransform = destinationLayer.transform,
  sourceWorldTransform: LayerTransform = sourceLayer.transform,
): PixelPatch {
  validateLayer(destinationLayer);
  validateLayer(sourceLayer);
  validateTransform(destinationWorldTransform);
  validateTransform(sourceWorldTransform);
  validateSelection(selection);
  if (points.leng

th === 0) throw new RangeError('Clone stamp stroke must contain at least one point');
  assertFinite(options.size, 'Clone stamp size');
  if (options.size <= 0) throw new RangeError('Clone stamp size must be greater than 0');
  assertUnit(options.hardness, 'Clone stamp hardness');
  assertUnit(options.opacity, 'Clone stamp opacity');
  assertFinite(options.sourceX, 'Clone stamp source X');
  assertFinite(options.sourceY, 'Clone stamp source Y');
  for (const [index, point] of points.entries()) {
    assertFinite(point.x, `Clone stamp point ${String(index)} x`);
    assertFinite(point.y, `Clone stamp point ${String(index)} y`);
    assertUnit(point.pressure ?? 1, `Clone stamp point ${String(index)} pressure`);
  }

  const radius = options.size / 2;
  const destinationInverse = invertTransform(destinationWorldTransform);
  const sourceInverse = invertTransform(sourceWorldTransform);
  const spacing = Math.max(0.25, radius * 0.5);

  // Convert source position from document space to source layer local space
  const sourceLocalPosition = transformPoint(sourceInverse, options.sourceX, options.sourceY);

  // Interpolate points into dabs, calculating source position for each dab
  const dabs: Array<{ x: number; y: number; pressure: number; sourceX: number; sourceY: number }> = [];
  const first = points[0];
  const firstDestinationPoint = transformPoint(destinationInverse, first.x, first.y);
  
  // Calculate the offset for aligned mode (in source layer local coordinates)
  const alignedOffset = {
    x: sourceLocalPosition.x - firstDestinationPoint.x,
    y: sourceLocalPosition.y - firstDestinationPoint.y,
  };

  dabs.push({
    x: first.x,
    y: first.y,
    pressure: first.pressure ?? 1,
    sourceX: options.aligned ? firstDestinationPoint.x + alignedOffset.x : sourceLocalPosition.x,
    sourceY: options.aligned ? firstDestinationPoint.y + alignedOffset.y : sourceLocalPosition.y,
  });

  for (let index = 1; index < points.length; index += 1) {
    const start = points[index - 1];
    const end = points[index];
    const distance = Math.hypot(end.x - start.x, end.y - start.y);
    const steps = Math.max(1, Math.ceil(distance / spacing));
    for (let step = 1; step <= steps; step += 1) {
      const progress = step / steps;
      const x = start.x + (end.x - start.x) * progress;
      const y = start.y + (end.y - start.y) * progress;
      const pressure = (start.pressure ?? 1) + ((end.pressure ?? 1) - (start.pressure ?? 1)) * progress;
      const destinationPoint = transformPoint(destinationInverse, x, y);
      
      let sourceX: number;
      let sourceY: number;
      if (options.aligned) {
        // Preserve the offset from the first destination point
        sourceX = destinationPoint.x + alignedOffset.x;
        sourceY = destinationPoint.y + alignedOffset.y;
      } else {
        // Always sample from the source origin
        sourceX = sourceLocalPosition.x;
        sourceY = sourceLocalPosition.y;
      }
      
      dabs.push({ x, y, pressure, sourceX, so

urceY });
    }
  }

  // Stroke working set: union of local dab bounds only (no full-layer densify).
  let strokeBounds: Bounds | null = null;
  for (const dab of dabs) {
    strokeBounds = unionBounds(
      strokeBounds,
      localDabBounds(destinationWorldTransform, destinationInverse, dab.x, dab.y, radius, destinationLayer.width, destinationLayer.height),
    );
  }
  if (strokeBounds === null || strokeBounds.right < strokeBounds.left) {
    return emptyPatch();
  }
  const regionLeft = strokeBounds.left;
  const regionTop = strokeBounds.top;
  const regionWidth = strokeBounds.right - strokeBounds.left + 1;
  const regionHeight = strokeBounds.bottom - strokeBounds.top + 1;
  const next = destinationLayer.pixelStore.read({
    x: regionLeft,
    y: regionTop,
    width: regionWidth,
    height: regionHeight,
  });
  const selectionRegion = readSelectionRegion(selection, dabs.map(d => ({ x: d.x, y: d.y })), radius);
  let changedBounds: Bounds | null = null;

  for (const dab of dabs) {
    const bounds = localDabBounds(
      destinationWorldTransform,
      destinationInverse,
      dab.x,
      dab.y,
      radius,
      destinationLayer.width,
      destinationLayer.height,
    );
    const { left, top, right, bottom } = bounds;
    for (let y = top; y <= bottom; y += 1) {
      for (let x = left; x <= right; x += 1) {
        const documentPoint = transformPoint(destinationWorldTransform, x, y);
        const falloff = dabCoverage(
          Math.hypot(documentPoint.x - dab.x, documentPoint.y - dab.y),
          radius,
          options.hardness,
        );
        const selected = selectionCoverage(
          selection,
          documentPoint.x,
          documentPoint.y,
          selectionRegion.buffer,
          selectionRegion.region,
        );
        const coverage = falloff * options.opacity * dab.pressure * selected;
        if (coverage <= 0) continue;
        
        // Sample from source layer at the calculated source position
        const sourceOffset = (Math.round(dab.sourceY) * sourceLayer.width + Math.round(dab.sourceX)) * 4;
        const sourceXIndex = clampIndex(Math.round(dab.sourceX), sourceLayer.width);
        const sourceYIndex = clampIndex(Math.round(dab.sourceY), sourceLayer.height);
        const sourceOffsetClamped = (sourceYIndex * sourceLayer.width + sourceXIndex) * 4;
        const sourcePixels = sourceLayer.pixelStore.read({
          x: sourceXIndex,
          y: sourceYIndex,
          width: 1,
          height: 1,
        });
        
        const offset = ((y - regionTop) * regionWidth + (x - regionLeft)) * 4;
        const before = [next[offset], next[offset + 1], next[offset + 2], next[offset + 3]];
        
        // Composite source pixels onto destination
        const sourceAlpha = (sourcePixels[3] ?? 0) / 255 * coverage;
        const destinationAlpha = (next[offset + 3] ?? 0) / 255;
        const outputAlpha = sourceAlpha + destinationAlpha * (1 - sourceAlp

ha);
        if (outputAlpha === 0) continue;
        
        for (let channel = 0; channel < 3; channel += 1) {
          const source = sourcePixels[channel] ?? 0;
          const destination = next[offset + channel] ?? 0;
          next[offset + channel] = Math.round(
            (source * sourceAlpha + destination * destinationAlpha * (1 - sourceAlpha)) / outputAlpha,
          );
        }
        next[offset + 3] = Math.round(outputAlpha * 255);
        
        if (
          before[0] !== next[offset] ||
          before[1] !== next[offset + 1] ||
          before[2] !== next[offset + 2] ||
          before[3] !== next[offset + 3]
        ) {
          changedBounds = include(changedBounds, x, y);
        }
      }
    }
  }
  return makePatchFromRegion(regionLeft, regionTop, regionWidth, next, changedBounds);
}

