  assertUnit(options.hardness, 'Clone stamp hardness');
  assertUnit(options.opacity, 'Clone stamp opacity');
  assertFinite(options.sourceX, 'Clone stamp source X');
  assertFinite(options.sourceY, 'Clone stamp source Y');
