      const y = start.y + (end.y - start.y) * progress;
      const pressure = (start.pressure ?? 1) + ((end.pressure ?? 1) - (start.pressure ?? 1)) * progress;
      const destinationPoint = transformPoint(destinationInverse, x, y);
      
      let sourceX: number;
      let sourceY: number;
